{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "credible_gap",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0009",
          "reason": "Conventional conflict de-escalation context; it does not show Abiy-specific existential-risk authority or nuclear conduct."
        },
        {
          "evidence_id": "E0010",
          "reason": "Peace-process context for the Tigray war; relevant to crisis management, but not to nuclear or other existential-risk decision-making."
        },
        {
          "evidence_id": "E0011",
          "reason": "Conventional conflict reporting about ceasefire collapse; context only for this chapter."
        },
        {
          "evidence_id": "E0012",
          "reason": "Human-rights and humanitarian-crisis context; it does not establish a ruler-attributed existential-risk choice."
        }
      ],
      "material_gaps": [
        {
          "gap": "No direct 2022 Abiy-specific nuclear, dual-use, or other existential-risk decision or command action.",
          "lenses": ["1B.1", "1B.2", "1B.3", "1B.5", "1B.7", "1B.8", "1B.9", "1B.10"],
          "best_source_or_query_direction": "Direct 2022 records from the PMO, defense/security files, IAEA/CTBTO/UNODA correspondence, or declassified official statements that show a ruler-attributed risk-bearing choice.",
          "why_it_matters": "Without a ruler-attributed risk-bearing action, the chapter remains an exposure-null case rather than a score-bearing one."
        }
      ],
      "reason": "The package fairly establishes Ethiopia's non-nuclear baseline and Abiy's limited exposure, but it does not show any Abiy-specific 2022 existential-risk decision. The conventional conflict material should stay context-only."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0011",
          "reason": "Duplicate Reuters syndication of the same August 2022 ceasefire-collapse story already represented by E0015; it should be consolidated to avoid double-counting the same event."
        },
        {
          "evidence_id": "E0016",
          "reason": "Self-justifying government narrative about TPLF responsibility; useful as ruler messaging, but not independent proof of the underlying factual claim."
        }
      ],
      "material_gaps": [
        {
          "gap": "Independent corroboration of who initiated the August 2022 renewed hostilities and how much control Abiy had over allied or Eritrean forces.",
          "lenses": ["2B.2", "2B.3", "2B.5", "2B.9"],
          "best_source_or_query_direction": "Independent conflict chronologies, AU/UN monitoring, or inquiry records on the August breakdown and allied-force conduct.",
          "why_it_matters": "This is the main remaining attribution issue for defensive necessity and proxy control."
        }
      ],
      "reason": "The chapter is balanced enough to show both de-escalation and repeated breakdowns, with civilian-harm evidence and contrary evidence preserved. The main weakness is residual attribution uncertainty on the August fighting and allied-force control, not omission of the core story."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0035",
          "reason": "Allegation-heavy Reuters report on Oromiya airstrikes; it should remain contextual unless independently corroborated."
        }
      ],
      "material_gaps": [
        {
          "gap": "Independent corroboration of the Oromiya airstrike allegations and a clearer command chain for the regional security actors involved.",
          "lenses": ["3B.1", "3B.2", "3B.9", "3B.10"],
          "best_source_or_query_direction": "Formal investigations, UN/OHCHR or EHRC follow-up, or court/inquiry records on the Oromiya incidents.",
          "why_it_matters": "This separates allegation from ruler-attributed physical-integrity harm."
        }
      ],
      "reason": "The dossier fairly separates official findings, watchdog reporting, and allegations, and it preserves the severe adverse record. The main weakness is one allegation-heavy item that needs corroboration before it can be treated as a strong adverse fact."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [
        {
          "gap": "Fresh 2022 evidence on contestability and institutional independence beyond the 2021 election legacy.",
          "lenses": ["4B.1", "4B.2", "4B.4", "4B.8", "4B.10"],
          "best_source_or_query_direction": "Election-board records, constitutional/court materials, legislative oversight records, or credible observer assessments focused on 2022 rather than the 2021 election aftermath.",
          "why_it_matters": "The chapter is partly resting on the prior election and media repression rather than direct 2022 contestability events."
        }
      ],
      "reason": "The chapter is usable as a stalled-opening account: it shows limited early restraint, then persistent media pressure and weak contestability. That is a fair 2022 picture, even if much of the strongest evidence is about the broader coercive environment rather than fresh election-year behavior."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0052",
          "reason": "A 2025 promotional results brief; useful only as low-weight retrospective corroboration and too remote to carry the 2022 chapter."
        }
      ],
      "material_gaps": [
        {
          "gap": "Independent 2022 budget-execution and household-distribution evidence tying reforms to welfare outcomes.",
          "lenses": ["5B.3", "5B.8", "5B.9", "5B.10"],
          "best_source_or_query_direction": "2022 budget-execution reports, household surveys, labor-market data, and independent macro assessments with regional breakdowns.",
          "why_it_matters": "This distinguishes announced reform from actual household welfare effect."
        }
      ],
      "reason": "The package fairly separates plans, shock context, implementation steps, and later corroboration. The weakest item is the 2025 results brief, which should not carry more weight than the 2022 evidence."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0054",
          "reason": "Duplicate of the UNICEF 2022 annual report claim already represented by E0051; consolidate to avoid inflating source breadth."
        },
        {
          "evidence_id": "E0064",
          "reason": "Same World Bank safety-net source family as E0053 with overlapping claims; it should be consolidated rather than counted as independent breadth."
        },
        {
          "evidence_id": "E0069",
          "reason": "Duplicate of the EU-funded education-restoration claim already represented by E0066; it should be merged to avoid repetition."
        },
        {
          "evidence_id": "E0070",
          "reason": "Duplicate UNICEF Bete/My Home claim already represented by E0065; it should be merged to avoid double-counting the same program."
        }
      ],
      "material_gaps": [
        {
          "gap": "More disaggregated 2022 welfare outcomes by region, displacement status, class, and gender, plus clearer direct ruler contribution versus donor or UN partnership.",
          "lenses": ["6B.2", "6B.3", "6B.8", "6B.9", "6B.10"],
          "best_source_or_query_direction": "Household surveys, program evaluations, and region-disaggregated administrative data for health, education, food security, and social protection.",
          "why_it_matters": "This separates humanitarian response from sustained ruler-attributed human-development gains."
        }
      ],
      "reason": "The package captures the real 2022 humanitarian crisis and the response, but it repeats several UNICEF and World Bank claims in ways that should be consolidated. Even so, the balance of need versus response is fairly presented."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0030",
          "reason": "Direct press-suppression evidence, but it is still better treated as scrutiny-context evidence than as direct proof of Abiy's personal deception or self-dealing."
        },
        {
          "evidence_id": "E0032",
          "reason": "Broad country-level repression report; relevant to the scrutiny environment, but not direct personal-integrity evidence."
        },
        {
          "evidence_id": "E0040",
          "reason": "Annual rights reporting on detention and expression restrictions; it supports the accountability climate, but not a personal honesty finding by itself."
        },
        {
          "evidence_id": "E0041",
          "reason": "Due-process and detention reporting is important context, but it still does not establish Abiy's own hidden benefit, assets, or direct deception."
        },
        {
          "evidence_id": "E0074",
          "reason": "The Chaka Project oversight gap is transparency context, not proof of concealed self-enrichment or personal benefit."
        },
        {
          "evidence_id": "E0075",
          "reason": "Journalist detention under the government is relevant to scrutiny suppression, but it is not direct evidence of personal financial honesty or dishonesty."
        },
        {
          "evidence_id": "E0076",
          "reason": "Same issue as E0075: useful for the accountability climate, but still indirect for personal integrity."
        },
        {
          "evidence_id": "E0077",
          "reason": "Conflict-narrative and arrest-count reporting is scrutiny context, not direct proof of personal deception or self-dealing."
        },
        {
          "evidence_id": "E0078",
          "reason": "Broad Freedom House repression summary; it should not be personalized into a ruler-honesty claim without a personal nexus."
        },
        {
          "evidence_id": "E0079",
          "reason": "HRW accountability critique is important background, but it is still not direct evidence of Abiy's own assets, concealment, or personal benefit."
        },
        {
          "evidence_id": "E0082",
          "reason": "Anecdotal charity and fundraising behavior is too thin to establish a broader integrity pattern and should not be over-weighted."
        }
      ],
      "material_gaps": [
        {
          "gap": "Audited personal-finance, asset, beneficial-ownership, procurement, or campaign-finance evidence tied to Abiy or close family, plus independent findings on whether anti-corruption enforcement was selective or even-handed.",
          "lenses": ["7B.3", "7B.4", "7B.6", "7B.7", "7B.9"],
          "best_source_or_query_direction": "Asset declarations, procurement/audit records, court or inquiry findings, and independent investigative reporting on family or close-network benefit.",
          "why_it_matters": "Personal integrity requires a ruler-specific nexus; generic repression or country corruption is not enough."
        }
      ],
      "reason": "This is the least secure chapter. It has some direct Abiy-nexus items, but much of the dossier is still country-level repression or scrutiny suppression that belongs primarily in 3B/4B unless tied to personal concealment, benefit, or retaliation. The record supports a mixed integrity environment, but not a confident personal-integrity conclusion."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0088",
          "reason": "Useful as indirect SOE-performance corroboration, but much of the gain may reflect post-pandemic rebound and it is not a clean Abiy competence measure."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct internal decision-trail evidence on implementation bottlenecks, replacement of blockers, and independent 2022 budget-execution audits for the reform package.",
          "lenses": ["8B.3", "8B.5", "8B.8", "8B.10"],
          "best_source_or_query_direction": "Cabinet minutes, board minutes for EIH and telecom bodies, budget-execution reports, and independent implementation audits.",
          "why_it_matters": "This distinguishes announced program from true execution and durability."
        }
      ],
      "reason": "The chapter is broadly coherent: it establishes a real 2022 program, concrete implementation, and some outcome signals, while preserving shock context and limits. The main weakness is that some outcome evidence is indirect or retrospective, so the chapter still rests partly on public statements and institution-level results."
    }
  ]
}
